  {
   "@type": "Question",
   "name": "Is it strange that my dog only goes outside?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "No. It's natural behavior that combines the instinct to keep where they sleep clean, scent marking, and walk habits."
   }
  },
  {
   "@type": "Question",
   "name": "Can an outdoor-only dog learn to go indoors?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Yes. Use a pad with outdoor scent on it or artificial grass, take them there when they're likely to go, and praise them when they succeed. It often takes several weeks."
   }
  },
  {
   "@type": "Question",
   "name": "What should I do on days we can't go for a walk?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Step outside the door even briefly to give them a potty chance, or use an indoor pad as a backup. If they can't go for more than a day and seem uncomfortable, talk to your vet."
   }
  },
  {
   "@type": "Question",
   "name": "My dog used to go at home but suddenly only goes outside.",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "It may be because the pad moved or they were scolded after an accident. If how often they pee or the color has changed, it could be a health issue, so talk to your vet."
   }
  }
 ]
